import type {HandoffScope} from './cashier-handoff';
export type DirectDepositRequest={id:string;scope:HandoffScope;session:string;bank:string;amount:string;reference:string;date:string;reason:string};
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
function obj(v:unknown){if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Invalid direct deposit data.');return v as Record<string,unknown>}
export function checkDirectDeposit(r:DirectDepositRequest){if(![r.id,r.session,r.bank,...Object.values(r.scope)].every(uuid)||! /^[1-9][0-9]{0,11}$/.test(r.amount)||! /^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Number.isFinite(Date.parse(r.date))||new Date(r.date).toISOString().slice(0,10)!==r.date||r.reference!==r.reference.trim()||r.reference.length<2||r.reference.length>120||r.reason!==r.reason.trim()||r.reason.length<4||r.reason.length>500||/[\x00-\x1f\x7f]/.test(r.reference+r.reason))throw Error('Check direct deposit details.');return r}
export function readDirectDepositReceipt(value:unknown,r:DirectDepositRequest){checkDirectDeposit(r);const v=obj(value);if(v.schema_version!==1||v.tenant_id!==r.scope.tenant||v.property_id!==r.scope.property||v.actor_id!==r.scope.actor||v.request_id!==r.id||v.session_id!==r.session||v.source_kind!=='direct_drawer'||v.bank_account_id!==r.bank||v.amount_minor!==r.amount||v.deposit_reference!==r.reference||v.deposit_date!==r.date||v.reason!==r.reason||v.bank_verified!==false||v.journal_posted!==false||typeof v.replayed!=='boolean')throw Error('Direct deposit receipt does not match the saved request.');return v}
export function readDirectDepositStatus(value:unknown,r:DirectDepositRequest){checkDirectDeposit(r);const v=obj(value);if(v.schema_version!==1||v.tenant_id!==r.scope.tenant||v.property_id!==r.scope.property||v.actor_id!==r.scope.actor||v.request_id!==r.id||typeof v.found!=='boolean'||typeof v.cancelled!=='boolean'||typeof v.voided!=='boolean'||v.found&&v.cancelled||!v.found&&v.voided)throw Error('Direct deposit recovery does not match.');if(v.found)readDirectDepositReceipt(v.result,r);else if(v.result!==null)throw Error('Unexpected deposit recovery result.');return {found:v.found,cancelled:v.cancelled,voided:v.voided}}
